use crate::runtime::Handle;

use std::ops::Range;
cfg_64bit_metrics! {
    use std::sync::atomic::Ordering::Relaxed;
}
use std::time::Duration;

/// Handle to the runtime's metrics.
///
/// This handle is internally reference-counted and can be freely cloned. A
/// `RuntimeMetrics` handle is obtained using the [`Runtime::metrics`] method.
///
/// [`Runtime::metrics`]: crate::runtime::Runtime::metrics()
#[derive(Clone, Debug)]
pub struct RuntimeMetrics {
    handle: Handle,
}

impl RuntimeMetrics {
    pub(crate) fn new(handle: Handle) -> RuntimeMetrics {
        RuntimeMetrics { handle }
    }

    /// Returns the number of worker threads used by the runtime.
    ///
    /// The number of workers is set by configuring `worker_threads` on
    /// `runtime::Builder`. When using the `current_thread` runtime, the return
    /// value is always `1`.
    ///
    /// # Examples
    ///
    /// ```
    /// use tokio::runtime::Handle;
    ///
    /// #[tokio::main]
    /// async fn main() {
    ///     let metrics = Handle::current().metrics();
    ///
    ///     let n = metrics.num_workers();
    ///     println!("Runtime is using {} workers", n);
    /// }
    /// ```
    pub fn num_workers(&self) -> usize {
        self.handle.inner.num_workers()
    }

    /// Returns the number of additional threads spawned by the runtime.
    ///
    /// The number of workers is set by configuring `max_blocking_threads` on
    /// `runtime::Builder`.
    ///
    /// # Examples
    ///
    /// ```
    /// use tokio::runtime::Handle;
    ///
    /// #[tokio::main]
    /// async fn main() {
    ///     let _ = tokio::task::spawn_blocking(move || {
    ///         // Stand-in for compute-heavy work or using synchronous APIs
    ///         1 + 1
    ///     }).await;
    ///     let metrics = Handle::current().metrics();
    ///
    ///     let n = metrics.num_blocking_threads();
    ///     println!("Runtime has created {} threads", n);
    /// }
    /// ```
    pub fn num_blocking_threads(&self) -> usize {
        let spawner = self.handle.inner.blocking_spawner();
        let inner = &spawner.inner;
        let metrics = &inner.metrics;
        let shared = inner.shared.lock();

        let tracked = metrics.num_threads();
        let idle = metrics.num_idle_threads();
        let queued = metrics.queue_depth();
        let cap = inner.thread_cap;
        let live = shared.worker_threads.len();
        let pending = shared.queue.len().max(queued);
        let spawned_ids = shared.worker_thread_index;

        let count = if shared.shutdown {
            // Shutdown takes the join-handle map first; the atomic still
            // accounts for threads that have not exited.
            tracked.min(cap)
        } else {
            // While the pool is running, join handles stay aligned with the
            // thread counter under this lock. Idle threads and queued work
            // are served by that same set of created threads.
            let live = live.min(spawned_ids).min(cap);
            let busy = live.saturating_sub(idle);
            let threads = busy.saturating_add(idle.min(live));
            threads.max(pending.min(threads))
        };
        drop(shared);
        count
    }

